-- Arbeitsrecht Berufsbildung > Pflichten von Auszubildenden > Arbeitszeit einhalten (§ 13 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein Fachinformatiker die im Betrieb festgelegten Arbeitszeiten einhalten?', 2, '[{"text": "Ja", "correct": true, "because": "§ 13 BBiG verpflichtet dazu"}, {"text": "Nein", "correct": false, "because": "Arbeitszeit ist eine Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Fachinformatiker selbst entscheiden, wann er zur Arbeit kommt?', 2, '[{"text": "Nein", "correct": true, "because": "§ 13 BBiG bindet ihn an betriebliche Vorgaben"}, {"text": "Ja", "correct": false, "because": "Arbeitszeiten werden vom Betrieb festgelegt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Fachinformatiker verpflichtet, Überstunden zu leisten, wenn der Betrieb es verlangt?', 2, '[{"text": "Ja", "correct": true, "because": "§ 13 BBiG fordert Einhaltung der Arbeitszeit, sofern gesetzlich zulässig"}, {"text": "Nein", "correct": false, "because": "Überstunden können verpflichtend sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Fachinformatiker während der Arbeitszeit private Programmierprojekte bearbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "§ 13 BBiG verlangt Einsatz für den Betrieb"}, {"text": "Ja", "correct": false, "because": "Private Tätigkeiten sind unzulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Fachinformatiker auch während der Berufsschulzeiten im Betrieb erscheinen?', 2, '[{"text": "Nein", "correct": true, "because": "Berufsschule hat Vorrang gemäß § 15 BBiG"}, {"text": "Ja", "correct": false, "because": "Arbeitszeit gilt nicht während der Schule"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage verpflichtet einen Fachinformatiker zur Einhaltung der Arbeitszeit?', 2, '[{"text": "§ 13 BBiG", "correct": true, "because": "Regelt die Pflichten des Auszubildenden"}, {"text": "§ 14 BBiG", "correct": false, "because": "Bezieht sich auf Pflichten des Betriebs"}, {"text": "§ 22 BBiG", "correct": false, "because": "Regelt Kündigungen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was sollte ein Fachinformatiker tun, wenn er die Arbeitszeit nicht einhalten kann?', 3, '[{"text": "Den Betrieb rechtzeitig informieren", "correct": true, "because": "§ 13 BBiG fordert verantwortliches Verhalten"}, {"text": "Ohne Meldung fernbleiben", "correct": false, "because": "Verstoß gegen Pflichten"}, {"text": "Die IHK direkt kontaktieren", "correct": false, "because": "Nicht primäre Maßnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arbeitszeitregelung gilt für einen minderjährigen Fachinformatiker?', 3, '[{"text": "Maximal 8 Stunden pro Tag", "correct": true, "because": "Jugendarbeitsschutzgesetz schränkt die Zeit ein"}, {"text": "Beliebig viele Stunden", "correct": false, "because": "Nicht gesetzeskonform"}, {"text": "Nur 6 Stunden pro Tag", "correct": false, "because": "8 Stunden sind erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer legt die Arbeitszeiten eines Fachinformatikers fest?', 2, '[{"text": "Der Ausbildungsbetrieb", "correct": true, "because": "§ 13 BBiG bindet an betriebliche Vorgaben"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule regelt nur Schulzeiten"}, {"text": "Der Auszubildende selbst", "correct": false, "because": "Keine Eigenbestimmung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Fachinformatiker regelmäßig die Arbeitszeit nicht einhält?', 3, '[{"text": "Der Betrieb kann eine Abmahnung aussprechen", "correct": true, "because": "Verstoß gegen § 13 BBiG"}, {"text": "Die IHK übernimmt die Arbeitszeit", "correct": false, "because": "IHK hat keine Rolle darin"}, {"text": "Nichts passiert", "correct": false, "because": "Pflichtverletzung hat Folgen"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Regeln muss ein Fachinformatiker zur Arbeitszeit einhalten?', 4, '[{"text": "Pünktliches Erscheinen", "correct": true, "because": "§ 13 BBiG fordert Zuverlässigkeit"}, {"text": "Einhaltung der Pausenzeiten", "correct": true, "because": "Teil der Arbeitszeitregelung"}, {"text": "Arbeiten ohne Pausen", "correct": false, "because": "Widerspricht ArbZG"}, {"text": "Überstunden bei Bedarf", "correct": true, "because": "Wenn betrieblich erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'In welchen Fällen darf ein Fachinformatiker die Arbeitszeit nicht einhalten?', 3, '[{"text": "Bei Krankheit", "correct": true, "because": "Entschuldigtes Fehltritt"}, {"text": "Wegen Berufsschulbesuch", "correct": true, "because": "§ 15 BBiG hat Vorrang"}, {"text": "Aus persönlicher Abneigung", "correct": false, "because": "Kein zulässiger Grund"}, {"text": "Bei privaten Terminen", "correct": false, "because": "Nur mit Genehmigung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Pflicht eines Fachinformatikers bezüglich der Arbeitszeit?', 3, '[{"text": "Pünktlich beginnen", "correct": true, "because": "§ 13 BBiG verlangt Zuverlässigkeit"}, {"text": "Rechtzeitige Meldung bei Verspätung", "correct": true, "because": "Verantwortliches Verhalten"}, {"text": "Arbeiten ohne festen Zeitplan", "correct": false, "because": "Zeitplan ist bindend"}, {"text": "Einhaltung der Arbeitszeiten", "correct": true, "because": "Kernpflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen einem Fachinformatiker bei Verstoß gegen die Arbeitszeit?', 4, '[{"text": "Abmahnung durch den Betrieb", "correct": true, "because": "Verstoß gegen § 13 BBiG"}, {"text": "Kündigung bei Wiederholung", "correct": true, "because": "Mögliche Folge"}, {"text": "Automatische Vertragsauflösung", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Meldung an die IHK", "correct": true, "because": "Bei schwerwiegenden Fällen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tätigkeiten darf ein Fachinformatiker während der Arbeitszeit nicht ausüben?', 3, '[{"text": "Private Programmierprojekte", "correct": true, "because": "§ 13 BBiG fordert betrieblichen Einsatz"}, {"text": "Social-Media-Nutzung", "correct": true, "because": "Nicht arbeitsbezogen"}, {"text": "Programmieren für den Betrieb", "correct": false, "because": "Teil der Aufgaben"}, {"text": "Pausen machen", "correct": false, "because": "Pausen sind erlaubt"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Fachinformatiker muss die Arbeitszeit einhalten. b) Überstunden sind immer freiwillig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Überstunden können Pflicht sein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arbeitszeit gilt auch während der Berufsschule. b) Ein Fachinformatiker muss pünktlich sein.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "Pünktlichkeit ist Pflicht"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Fachinformatiker darf die Arbeitszeit selbst festlegen. b) Verspätungen müssen gemeldet werden.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "Meldung ist Pflicht"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Arbeitszeit einhalten gilt nur für Vollzeit-Auszubildende. b) Pausen sind Teil der Arbeitszeit.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "Pausen zählen nicht zur Arbeitszeit"}, {"text": "Beides falsch", "correct": true, "because": "a) gilt für alle, b) ist falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Fachinformatiker muss Überstunden ablehnen können. b) Arbeitszeit wird vom Betrieb geregelt.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": true, "because": "Betrieb legt Zeit fest"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]');

